import { Component, inject, OnInit } from '@angular/core';
import { CommonModule, TitleCasePipe } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Tramite } from '../../../models/tramite';
import { StandarResponse } from '../../../services/http.service';
import { TramiteService } from '../../../controllers/tramite.service';

@Component({
  selector: 'app-tramites-list',
  standalone: true,
  imports: [CommonModule, RouterModule, TitleCasePipe],
  templateUrl: './tramites-list.html',
  styleUrl: './tramites-list.css',
})
export class TramitesListComponent implements OnInit {
  tramites: Tramite[] = [];
  loading = true;
  Math = Math;
  pagination = {
    currentPage: 1,
    perPage: 2,
    totalPages: 0,
    totalItems: 0,
  };

  private tramiteService = inject(TramiteService);


  ngOnInit(): void {
    this.loadTramites();
  }

  async loadTramites(page = 1): Promise<void> {
    try {
      const response: StandarResponse<Tramite[]> = await this.tramiteService.getTramites(page, this.pagination.perPage);
      this.tramites = response.data || [];
      console.log('Trámites cargados:', this.tramites);

      this.pagination = {
        currentPage: response.page || page,
        perPage: response.per_page || this.pagination.perPage,
        totalPages: response.total_pages || 0,
        totalItems: response.total_items || 0,
      };
    } catch (error) {
      console.error('Error loading trámites:', error);
    }
  }

  getStatusBadgeClass(status: string | undefined): string {
    if (!status) return 'bg-secondary';

    const statusClasses: Record<string, string> = {
      APROBADA: 'bg-success',
      INICIADA: 'bg-warning',
      RECIBIDA: 'bg-info',
      EN_REVISION: 'bg-info',
      VALIDADA: 'bg-success',
      RECHAZADA: 'bg-danger',
      CANCELADA: 'bg-dark',
    };

    return statusClasses[status] || 'bg-secondary';
  }

  getStatusIcon(status: string | undefined): string {
    if (!status) return 'bi-question-circle';

    const statusIcons: Record<string, string> = {
      APROBADA: 'bi-check-circle-fill',
      INICIADA: 'bi-clock-history',
      RECIBIDA: 'bi-envelope-check',
      EN_REVISION: 'bi-hourglass-split',
      VALIDADA: 'bi-check-circle',
      RECHAZADA: 'bi-x-circle-fill',
      CANCELADA: 'bi-dash-circle',
    };

    return statusIcons[status] || 'bi-question-circle';
  }

  getCardBorderClass(status: string | undefined): string {
    if (!status) return 'border-secondary';

    const borderClasses: Record<string, string> = {
      APROBADA: 'border-success',
      INICIADA: 'border-warning',
      RECIBIDA: 'border-info',
      EN_REVISION: 'border-info',
      VALIDADA: 'border-success',
      RECHAZADA: 'border-danger',
      CANCELADA: 'border-dark',
    };

    return borderClasses[status] || 'border-secondary';
  }

  getTipoLabel(tipo: string | undefined): string {
    if (!tipo) return 'Sin tipo';

    const tipoLabels: Record<string, string> = {
      inversion_privada: 'Impuesto sobre la nómina',
      tratamiento_agua: 'Tratamiento de Agua',
    };

    return tipoLabels[tipo] || tipo;
  }

  getTipoIcon(tipo: string | undefined): string {
    if (!tipo) return 'bi-question-circle';

    const tipoIcons: Record<string, string> = {
      inversion_privada: 'bi-currency-dollar',
      tratamiento_agua: 'bi-droplet',
    };

    return tipoIcons[tipo] || 'bi-question-circle';
  }

  goToPage(page: number): void {
    if (page >= 1 && page <= this.pagination.totalPages) {
      this.loadTramites(page);
    }
  }

  get paginationArray(): number[] {
    const pages: number[] = [];
    const maxVisible = 5;
    let start = Math.max(1, this.pagination.currentPage - Math.floor(maxVisible / 2));
    const end = Math.min(this.pagination.totalPages, start + maxVisible - 1);

    if (end - start < maxVisible - 1) {
      start = Math.max(1, end - maxVisible + 1);
    }

    for (let i = start; i <= end; i++) {
      pages.push(i);
    }

    return pages;
  }

  getCompletitudProgress(tramite: Tramite): { value: number; color: string } {
    const totalSections = 10;
    let filledSections = 0;

    if (tramite.empresa) filledSections++;
    if (tramite.empresa_vinculada) filledSections++;
    if (tramite.empresa_beneficiada_id) filledSections++;
    if (tramite.proyecto_inversion) filledSections++;
    if (tramite.escrito_libre) filledSections++;
    if (tramite.anexos_empleos?.length) filledSections++;
    if (tramite.anexo_empleo_indirecto) filledSections++;
    if (tramite.anexo_estudiante) filledSections++;
    if (tramite.anexos_inversiones?.length) filledSections++;
    if (tramite.anexos_proveeduria?.length) filledSections++;

    const percentage = Math.round((filledSections / totalSections) * 100);

    let color = 'bg-danger';
    if (percentage >= 75) color = 'bg-success';
    else if (percentage >= 50) color = 'bg-warning';
    else if (percentage >= 25) color = 'bg-info';

    return { value: percentage, color };
  }

  getDaysSinceCreation(createdAt: string | undefined): number {
    if (!createdAt) return 0;
    const createdDate = new Date(createdAt);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - createdDate.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  }

  getLastUpdated(updatedAt: string | null | undefined, createdAt: string | undefined): string {
    const date = updatedAt || createdAt;
    if (!date) return 'N/A';
    const updatedDate = new Date(date);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - updatedDate.getTime());
    const diffHours = Math.ceil(diffTime / (1000 * 60 * 60));
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffHours < 24) {
      return `Hace ${diffHours} hora${diffHours !== 1 ? 's' : ''}`;
    } else if (diffDays === 1) {
      return 'Ayer';
    } else {
      return `Hace ${diffDays} días`;
    }
  }

  getProgressBarColor(percentage: number): string {
    if (percentage >= 75) return 'bg-success';
    if (percentage >= 50) return 'bg-warning';
    if (percentage >= 25) return 'bg-info';
    return 'bg-danger';
  }

  getProyectoInversionName(tramite: Tramite): string {
    if (tramite.proyecto_inversion) {
      return tramite.proyecto_inversion.descripcion_proyecto?.substring(0, 50) + '...' || 'Proyecto registrado';
    }
    return 'Sin proyecto';
  }

  getUsuarioNombreCorto(tramite: Tramite): string {
    const nombre = tramite.usuario?.name;
    if (!nombre) return 'N/A';
    const parts = nombre.split(' ');
    return parts[0] || 'N/A';
  }
}