import { Component, Input, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Header, TablaComponent, TableDefinition, RowButton, RowButtonClickEvent } from '../../../../../shared/tabla/tabla.component';
import { TramiteDocumentoService } from '../../../../../controllers/tramite-documento.service';
import { TramiteDocumento } from '../../../../../models/tramite-documento';
import { Conditional } from '../../../../../controllers/super.service';

@Component({
  selector: 'app-documentos-tramite',
  standalone: true,
  imports: [CommonModule, TablaComponent],
  templateUrl: './documentos-tramite.component.html',
  styleUrl: './documentos-tramite.component.css',
})
export class DocumentosTramiteComponent implements OnInit {
  @Input() tramiteId: number | undefined;

  tramiteDocumentoService = inject(TramiteDocumentoService);

  tableDefinition: TableDefinition = {
    emptyMsg: 'No hay documentos registrados',
    columns: [
      {
        header: 'Nombre',
        key: 'nombre'
      } as Header,
      {
        header: 'Fecha Creación',
        key: 'created_at',
        pipe: 'date',
        dateFormat: 'dd/MM/yyyy HH:mm'
      } as Header,
    ]
  };

  rowButtons: RowButton[] = [
    {
      key: 'ver-documento',
      text: 'Ver',
      style: {
        button: 'btn btn-sm btn-outline-primary',
        icon: 'bi bi-file-pdf'
      }
    }
  ];

  getConditionals: Conditional[] = [];

  ngOnInit(): void {
    if (this.tramiteId) {
      this.getConditionals = [
        { key: 'tramite_id', operator: '=', value: this.tramiteId },
        { key: 'deleted_at', operator: 'IS NULL', value: null }
      ];
    }
  }

  onRowButtonClick(event: RowButtonClickEvent<TramiteDocumento>): void {
    if (event.key === 'ver-documento') {
      this.verDocumento(event.row);
    }
  }

  async verDocumento(documento: TramiteDocumento): Promise<void> {
    if (documento.id) {
      await this.tramiteDocumentoService.verDocumento(documento.id, false);
    }
  }
}